def attr(type, name, default_value=None, inout_trait="inout", extra_trait=None, comment=""):
    if extra_trait is None:
        extra_trait = []
    return {
        "category": "attribute",
        "trait": [inout_trait] + extra_trait,
        "default_value": default_value,
        "type": type,
        "name": name,
        "comment": comment
