  if(CMAKE_HIP_STANDARD)
    # Use CMAKE_HIP_STANDARD if set
    set(${STANDARD}
        ${CMAKE_HIP_STANDARD}
        PARENT_SCOPE)
  elseif(CMAKE_CXX_STANDARD)
