text((await tools.exec_command({cmd:"PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
import os,subprocess
# Evaluate the real TCP endpoint selector directly, without producing a disk artifact.
source=open('lct/pmi/pmi_wrapper_tcp.cpp').read()
start=source.index('bool select_endpoint(');end=source.index('\nstd::string endpoint_help()',start)
selector=source[start:end]
harness='''#include <cstdlib>
#include <climits>
#include <iostream>
struct endpoint_spec_t {const char* source;const char* addr_name;const char* port_name;};
struct endpoint_choice_t {const endpoint_spec_t* spec;const char* addr;const char* port;};
const endpoint_spec_t k_endpoint_specs[]={{"LCT","LCT_MASTER_ADDR","LCT_MASTER_PORT"},{"LCI","LCI_MASTER_ADDR","LCI_MASTER_PORT"},{"MASTER","MASTER_ADDR","MASTER_PORT"}};
bool parse_int_no_fail(const char* v,int min,int max){if(!v)return false;char* e;long p=strtol(v,&e,10);return e!=v&&!*e&&p>=min&&p<=max;}
'''+selector+'\nint main(){endpoint_choice_t e={};std::cout<<select_endpoint(&e)<<"\\n";}\n'
# Compiler syntax verification only, with all output piped.
r=subprocess.run(['c++','-x','c++','-','-fsyntax-only'],input=harness,text=True,capture_output=True)
print('TCP selector harness syntax check:',r.returncode,r.stderr)
# Verify the version file helper uses the nested project version, not its parent's version.
helper=open('/usr/share/cmake-3.22/Modules/WriteBasicConfigVersionFile.cmake').read()
print('CMake version helper default:',helper[helper.index('if("${CVF_VERSION}" STREQUAL "")'):helper.index('if("${CVF_VERSION}" STREQUAL "")')+315])
PY",max_output_tokens:1200})).output);
